<?php use CmuLms\View; $title='Attempt review'; include __DIR__.'/../layout/header.php'; ?>
<section class="hero"><span><?=View::e($attempt['code'])?> · Attempt review</span><h1><?=View::e($attempt['exam_title'])?></h1><p><?=View::e($attempt['name'])?> · <?=View::e($attempt['id_number'])?> · Attempt <?=View::e($attempt['attempt_number'])?> · <?=View::e($attempt['status'])?></p><?php if($attempt['score']!==null):?><p>Recorded score: <?=View::e($attempt['score'])?> / <?=View::e($attempt['max_score'])?></p><?php endif;?></section>
<?php foreach($questions as $i=>$question): $options=json_decode($question['options']??'{}',true)?:[];$correct=json_decode($question['answer']??'[]',true)?:[];$given=$answers[$question['id']]??''; ?><section class="card"><h3>Question <?=$i+1?></h3><p><?=nl2br(View::e($question['prompt']))?></p><ol type="A"><?php foreach($options as $key=>$option):?><li><?=View::e($option)?><?php if((string)$key===(string)$given):?> <strong>Student answer</strong><?php endif;?><?php if(in_array((string)$key,array_map('strval',$correct),true)):?> <span class="badge">Correct</span><?php endif;?></li><?php endforeach;?></ol><?php if($given===''&&$options):?><p class="muted">No answer saved.</p><?php endif;?></section><?php endforeach; ?>
<?php include __DIR__.'/../layout/footer.php'; ?>
